    panel.open = true;
    setStatus(status, `${pinnedIds().length} gemerkte Datensätze aus dem Link geladen – «Vergleichen» öffnet die Gegenüberstellung.`, 'info');
  }

  return { open: openCompare, close: closeCompare, add: addSelected, clear: clearAll };
}

