    (!expectTo || appliedPeriod.to === expectTo) &&
    appliedPeriod.count >= 1 &&
    appliedPeriod.state.length > 0,
  `${selectedId ?? 'no record'} -> ${JSON.stringify(appliedPeriod)}`,
);

