  const total = manifest?.canvases?.length ?? 0;
  if (total === 0) return;
  // The sheet number comes from the shareable state and is clamped to what the
  // work actually has; a mismatch (e.g. after switching records) is written back
  // so the URL never points at a sheet that does not exist.
  page = Math.max(0, Math.min(total - 1, Math.floor(Number(ctx.store.getState().sheet) || 1) - 1));
  if (ctx.store.getState().sheet !== page + 1) ctx.store.update({ sheet: page + 1 });
  const canvas = manifest.canvases[page];
  if (!canvas) return;
  const pageLabel = qs('#page-label');
