test('the sheet of a multi-sheet work is shareable and clamped', () => {
  const query = stateToQuery({ ...STATE_DEFAULTS, selected: 'e-rara:6485160', sheet: 2 });
  const params = new URLSearchParams(query);
  assert.equal(params.get(PARAM.sheet), '2');
  assert.equal(readStateFromUrl(`?${query}`).sheet, 2, 'the sheet survives the round-trip');
  assert.equal(new URLSearchParams(stateToQuery({ ...STATE_DEFAULTS })).has('sh'), false, 'sheet 1 is the default and stays out of the URL');
  assert.equal(readStateFromUrl('?sel=e-rara:6485160').sheet, 1, 'a detail link without a sheet opens the first one');

  const store = createStore({ initial: { sheet: 1 } });
  const seen = [];
  store.subscribe((state, changed) => seen.push([state.sheet, changed.join(',')]));
  store.update({ sheet: 3 });
  assert.deepEqual(seen, [[3, 'sheet']]);
  store.update({ sheet: 3 });
  assert.equal(seen.length, 1, 'the same sheet does not notify twice');
});

