+  assert.equal(sanitise({ ...STATE_DEFAULTS, sheet: 2.9 }).sheet, 2, 'fractions are floored');
+  assert.equal(sanitise({ ...STATE_DEFAULTS, sheet: 'x' }).sheet, 1);
+  assert.equal(sanitise({ ...STATE_DEFAULTS, sheet: 1e6 }).sheet, 999);
+});

