  const sheetTwo = await cdp.eval(`(() => ({
    label: document.querySelector('#page-label')?.textContent || '',
    prevDisabled: document.querySelector('#page-prev')?.disabled,
    nextDisabled: document.querySelector('#page-next')?.disabled,
    alt: document.querySelector('.app-viewer__image')?.alt || '',
    sheetParam: new URLSearchParams(location.search).get('sh') || '',
  }))()`);
  const expectedTotal = String(multiSheet.canvasCount);
  check(
    'a real multi-sheet work offers working sheet navigation',
    sheetOne.navHidden === false &&
      sheetOne.label === `Blatt 1 von ${expectedTotal}` &&
      sheetOne.prevDisabled === true &&
      sheetTwo.label === `Blatt 2 von ${expectedTotal}` &&
      sheetTwoSrc !== sheetOne.src &&
      sheetTwo.prevDisabled === false &&
      sheetTwo.sheetParam === '2',
    `${multiSheet.id} (${expectedTotal} Blatt) · "${sheetOne.label}" -> "${sheetTwo.label}" sh=${sheetTwo.sheetParam} ${sheetOne.src.slice(-40)} -> ${sheetTwoSrc.slice(-40)}`,
  );

  // The sheet number is part of the shareable URL: a link with ?sh=2 must open
  // sheet 2 directly, and a single-sheet record must clamp it back to 1.
  await cdp.send('Page.navigate', { url: `${BASE_URL}/?sel=${encodeURIComponent(multiSheet.id)}&sh=2` });
  await cdp.waitFor(`document.querySelector('#viewer-stage')?.dataset.state === 'ready'`, { label: 'shared sheet link', timeout: 25_000 });
  const sharedSheet = await cdp.eval(`(() => ({
    label: document.querySelector('#page-label')?.textContent || '',
    prevDisabled: document.querySelector('#page-prev')?.disabled,
    src: document.querySelector('.app-viewer__image')?.src || '',
  }))()`);
  const singleSheet = [...recordIndex.values()].find((record) => record.iiifManifest && (record.canvasCount ?? 0) === 1);
  let clamped = null;
  if (singleSheet) {
    await cdp.send('Page.navigate', { url: `${BASE_URL}/?sel=${encodeURIComponent(singleSheet.id)}&sh=2` });
    await cdp.waitFor(`document.querySelector('#viewer-stage')?.dataset.state === 'ready'`, { label: 'clamped sheet link', timeout: 25_000 });
    clamped = await cdp.eval(`(() => ({
      label: document.querySelector('#page-label')?.textContent || '',
      sheetParam: new URLSearchParams(location.search).get('sh'),
      navHidden: document.querySelector('#page-nav')?.hidden,
    }))()`);
  }
  check(
    'a shared ?sh= link opens the requested sheet and is clamped to the work',
    sharedSheet.label === `Blatt 2 von ${expectedTotal}` &&
      sharedSheet.prevDisabled === false &&
      sharedSheet.src !== sheetOne.src &&
      (!singleSheet || (clamped.label === 'Blatt 1 von 1' && clamped.sheetParam === null && clamped.navHidden === true)),
    `${sharedSheet.label} · sh=2 link ${sharedSheet.src.slice(-38)}${singleSheet ? ` · single-sheet clamp -> ${clamped.label}, sh=${clamped.sheetParam}` : ' · no single-sheet record in the seed'}`,
  );
} else {
  check('a real multi-sheet work offers working sheet navigation', false, 'no multi-sheet record in the seed');
  check('a shared ?sh= link opens the requested sheet and is clamped to the work', false, 'no multi-sheet record in the seed');
}

